def test_no_shell_true(self):
        for path in _all_script_files():
            ext = _ext(path)
            content = _read(path)
            for pattern in _SHELL_FLAG_BY_EXT.get(ext, []):
                assert not re.search(pattern, content), \
                    f"Found shell opt-in {pattern!r} in {path}"
